import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Login from './pages/Login';
import StudentDashboard from './pages/StudentDashboard';
import ExportMarks from './pages/ExportMarks';
import SubjectMarks from './pages/SubjectMarks'; // <-- Import your new page
import './global.css';

function App() {
  return (
    <Router>
      <Routes>
        <Route path='/' element={<StudentDashboard />} />
        <Route path='/login' element={<Login />} />
        <Route path='/export-marks' element={<ExportMarks />} />
        <Route path='/subject-marks' element={<SubjectMarks />} /> {/* Add this route */}
      </Routes>
    </Router>
  );
}

export default App;
